"""Produce a self-contained large-type verification report from executed test records."""
from pathlib import Path
import json,datetime,html,base64,hashlib
R=Path(__file__).resolve().parents[1];O=R/'reports';O.mkdir(exist_ok=True)
items=[('核心数学与算法','math-results.json'),('新增证明与计算图解','proof-results.json'),('NumPy / SciPy 独立核验','independent-results.json'),('Chromium 页面与交互','browser-results.json')]
loaded=[(label,fn,json.loads((O/fn).read_text())) for label,fn in items]
counts=json.loads((R/'data/edition.json').read_text());browser=loaded[-1][2]
failed=sum(x['failed'] for _,_,x in loaded);total=sum(x['tests'] for _,_,x in loaded);passed=sum(x['passed'] for _,_,x in loaded);assertions=sum(x.get('assertions',0) for _,_,x in loaded)
font_checks=[r['details'] for r in browser['results'] if r['status']=='pass' and r['name'].startswith('Large type and responsive')]
minimum=min(r['minimum_px'] for r in font_checks);audited=sum(r['text_nodes'] for r in font_checks)
bundle=R/'Optimization_Explorable.html';sha=hashlib.sha256(bundle.read_bytes()).hexdigest();stamp=datetime.datetime.now(datetime.timezone.utc).isoformat()
def e(s):return html.escape(str(s))
def inline_file(p,mime):return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
def image(fn,title):
 p=O/'screenshots'/fn
 return f'<figure><figcaption>{e(title)}</figcaption><details><summary>展开原始像素截图 · 宽图可横向滚动</summary><div class="shot-viewport"><img src="{inline_file(p,"image/png")}" alt="{e(title)}" loading="lazy"></div></details></figure>' if p.exists() else ''

css='''*{box-sizing:border-box}html{font-size:22px}body{font-family:"Microsoft YaHei",system-ui,sans-serif;background:#f5f4ed;color:#253c34;margin:0;line-height:1.9;font-size:24px}main{max-width:1160px;margin:auto;padding:50px 32px}h1{font-size:44px;line-height:1.5}h2{font-size:32px;margin-top:46px}h3{font-size:27px}p,li{font-size:24px}small,.meta{font-size:22px;color:#52665d}.eyebrow{font-size:22px;color:#087962}a{color:#087962;text-underline-offset:5px;overflow-wrap:anywhere}.status,.callout{border-left:4px solid #087962;padding:24px 28px;background:#e4f0e7;margin:28px 0}.warning{border-left-color:#a8482c}.scroll{overflow:auto;max-width:100%}table{border-collapse:collapse;width:100%;font-size:22px}th,td{text-align:left;border-bottom:1px solid #cbd3c8;padding:18px 14px;vertical-align:top}pre{font-size:22px;line-height:1.8;padding:22px;background:#fffef9;overflow:auto;max-height:600px}code{font-size:22px;overflow-wrap:anywhere}details{border-top:1px solid #cbd3c8;padding:18px 0}summary{cursor:pointer;font-size:24px}.shot-viewport{overflow:auto;max-width:100%}img{display:block;max-width:none;height:auto;border:1px solid #cbd3c8}figure{margin:32px 0}figcaption{font-size:24px;margin-bottom:18px}.checks{font-size:22px}.hash{font-size:22px;word-break:break-all}.source{font-size:22px}ul{padding-left:28px}@media(max-width:640px){main{padding:28px 18px}h1{font-size:36px}.scroll table{min-width:670px}p,li{font-size:24px}pre{padding:16px}}'''
rows=''.join(f'<tr><td>{e(label)}</td><td>{d["tests"]}</td><td>{d["passed"]}</td><td>{d["failed"]}</td><td>{d.get("assertions","—")}</td><td><a href="{inline_file(O/fn,"application/json")}" download="{fn}">原始记录</a></td></tr>' for label,fn,d in loaded)
parts=[f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>最优化 · 大字证明版验证报告</title><style>{css}</style></head><body><main><span class="eyebrow">最优化 / 大字证明版</span><h1>排版、推导与动画，都有可查的验证记录。</h1><p class="meta">报告生成：{e(stamp)}<br>浏览器：Chromium {e(browser["browser"])}</p><div class="status"><strong>{"全部通过" if not failed else "存在失败"} · {passed}/{total} 项测试</strong><br>{assertions:,} 次数值／结构断言。测试项包含参数扫描与交互检查，不代表同等数量的独立定理证明。</div><p><a href="../Optimization_Explorable.html">返回完整工程中的讲义</a></p><h2>本版内容</h2><p>{counts["chapters"]} 节讲义，{counts["proofs"]} 组详细证明，{counts["proof_steps"]} 个证明步骤，{counts["proofs"]} 幅可播放计算图解，{counts["labs"]} 个算法／参数实验，{counts["formulas"]} 条编排公式。</p><p>正文默认 26px，窄屏 24px；界面、来源、图例与数学脚标以 22px 为下限设计。证明默认完整展开，导读只改变强调位置。图解参数动画与证明导读相互独立，所有数值来自公式或可复现的算法状态。</p><h2>实际执行结果</h2><div class="scroll"><table><thead><tr><th>套件</th><th>测试</th><th>通过</th><th>失败</th><th>断言</th><th>证据</th></tr></thead><tbody>{rows}</tbody></table></div>']
parts+=['<h2>字号、布局与交互</h2>',f'<p>在 360、390、768、1440、1920px 五种宽度下，对全部章节及资料库、目录覆盖、依赖图做检查。共 {len(font_checks)} 组排版记录，检查 {audited:,} 个具有文字的元素；其中包括 MathML 的脚标以及换算 SVG 显示比例后的图中文字。最小测得字号约 {minimum:.2f}px，SVG 像素取整容差为 0.1px；没有发现文档级横向溢出。</p>', '<p>浏览器检查了全部 40 个证明面板的步骤定位、前进／后退、完整展开、参数变更、图解回退、播放／暂停；以及 37 个算法实验的参数与案例、历史恢复、单步、重置。另验证了动画到终点及换章后停止、减少动态效果偏好、字号档位、主题、来源链接、页码映射、266 项教材目录检索、资料全文检索以及 JSON／CSV 实际导出。</p>',f'<p>控制台错误：{len(browser["console_errors"])}；页面 JavaScript 错误：{len(browser["page_errors"])}。讲义没有主动发起外网请求；原始网站链接在主动点击后才访问。</p>']
parts+=['<h2>数学核验重点</h2>','<p>FISTA 验证 q 递推、组合能量下降及目标差上界；ADMM 验证完整轮次的原始—对偶能量、残差预算及单调性所需的起始索引。其他新增核验包括谱方向递推、凸性与支撑余量、邻近上界、牢固非扩张、最大 k 项阈值表达式、软阈值零惩罚边界及分段 Newton 余项。原有数值套件继续检查线搜索、拟牛顿、信赖域、约束与流形等算法。</p>', '<p>独立 NumPy／SciPy 核验不调用同一套 JavaScript 求解逻辑：用 SVD 核验核范数邻近算子，用 LAPACK 核验谱，用约束优化核验二维 LASSO，用独立搜索核验信赖域等。有限样本检验确认实现性质，不代替正文中面向一般输入的数学证明。</p>']
parts+=['<h2>本次发现并修复的问题</h2>','<div class="callout"><strong>零惩罚边界的 Newton 掩码</strong><p>λ=0 时软阈值是恒等映射，零输入处也必须取导数 1。旧掩码按一般阈值边界取 0，在构造的零输入案例上返回了错误矩阵元素 1，而正确值为 0.5。新增测试先失败，再修正为 λ=0 时 D=I，并重新运行全部套件。该失败记录保留供核对。</p><p>证明同时区分“由软阈值分段构造的 Newton 矩阵”和残差的 Clarke Jacobian 集合：不把广义链式法则的包含关系冒称等号，而直接验证所需的 Newton 余项。另补入奇异仿射输入映射的检查。</p></div>','<p>浏览器测试的一次导航检查在地址散列已变化、目标章节尚未完成更新时读取状态，产生竞态失败。测试改为同时等待目标章节和抽屉关闭，未绕过指针可操作性检查；随后的完整回归通过。首次全套浏览器执行因命令时限中断，不计入通过结果。</p>']
for fn,label in [('proof-zero-penalty-before-fix.json','零惩罚修复前记录'),('browser-navigation-wait-before-fix.json','导航等待修复前记录')]:
 if (O/fn).exists():parts.append(f'<p><a href="{inline_file(O/fn,"application/json")}" download="{fn}">{label}</a></p>')
parts+=['<h2>原始出处与收录边界</h2>','<p>教材与课程资料下载自北京大学文再文老师网站。教材作者为刘浩洋、户将、李勇锋、文再文；其他教案的贡献者以原文件及网站说明为准。资料表逐项保留实际 URL，不把下载清单元数据冒称教材原文。</p>','<p class="source"><a href="https://faculty.bicmr.pku.edu.cn/~wenzw/optbook.html">文再文老师最优化教材与电子教案主页</a><br><a href="https://faculty.bicmr.pku.edu.cn/~wenzw/opt-2026-fall.html">2026 年秋季课程主页</a></p>','<p>原始 65 个文件保持字节不变，其中 64 个有公开原始 URL，1 个为下载清单元数据；41 份 PDF 共 1,990 个物理页。编辑后的讲义、目录、说明与报告已去除对话来源措辞和具体机器路径；公开原文及原作者署名保留。资料库原始提取文本仍可能含数学公式乱码，原 PDF 是核验依据。</p>','<p>“详细证明”指本版编排的 40 组核心结论与算法性质，不是原始 1,990 页中每一定理、习题与变体的完整重写。33 个未收录直链保留原始入口，不被标作失效链接。没有运行教材的 MATLAB／商业求解器性能实验。</p>', '<h2>测试边界</h2>', '<div class="callout warning"><p>执行环境的浏览器管理策略阻止直接 file: 导航。本轮已实际尝试并记录该限制；没有修改或绕过策略。页面测试通过在真实 Chromium 中加载同一份自包含 HTML 完成，并单独加载分文件脚本与样式核验源码入口。</p><p>因此这些结果覆盖 DOM、SVG、MathML、控件和数值逻辑，但不构成原生 PDF 查看器、Firefox、Safari 或直接文件导航的通过记录。网站链接的实际下载可用性也不属于本轮浏览器测试。</p></div>']
parts+=['<h2>本版界面实测截图</h2>']
for fn,t in [('home-desktop.png','首页：大字号与阅读结构'),('fista-energy-desktop.png','FISTA：组合能量与分量'),('fista-proof-desktop.png','逐行证明：原理、公式与图示观察'),('convex-mobile.png','窄屏：图形标签不缩小'),('proof-mobile.png','窄屏：长公式在自身容器滚动'),('admm-energy-desktop.png','ADMM：能量与残差'),('library-desktop.png','资料库：原始网站来源逐项可查')]:parts.append(image(fn,t))
parts+=['<h2>逐项记录</h2>']
for label,fn,d in loaded:
 parts.append(f'<details><summary>{e(label)} · {d["passed"]}/{d["tests"]}</summary><div class="scroll"><table><thead><tr><th>测试</th><th>状态</th></tr></thead><tbody>'+''.join(f'<tr><td>{e(q["name"])}</td><td>{e(q["status"])}</td></tr>' for q in d['results'])+'</tbody></table></div></details>')
parts+=['<h2>复现与版本完整性</h2>','<pre>python tools/build_single.py\nnode tests/math.test.cjs\nnode tests/proofs.test.cjs\npython tests/independent.py\npython tests/browser.py\npython tools/build_report.py</pre>',f'<p>本次所验证自包含 HTML 的 SHA-256：</p><p class="hash">{sha}</p><p>测试反映当前源码、输入与运行条件；修改后应重新执行，不能沿用本份通过状态。</p></main></body></html>']
content=''.join(parts);(O/'test-report.html').write_text(content)
md=f'''# 最优化 · 大字证明版验证报告\n\n生成：{stamp}\n\n{passed}/{total} 项测试通过，失败 {failed}；数值及结构断言 {assertions:,} 次。\n\n34 节讲义，40 组证明，264 个步骤，40 幅计算图解，37 个实验，298 条公式。\n\n'''
for label,fn,d in loaded:md+=f'- {label}：{d["passed"]}/{d["tests"]}；记录 {fn}\n'
md+=f'''\n字体与布局：{len(font_checks)} 组，检查 {audited:,} 个文字元素；最小显示字号约 {minimum:.2f}px，SVG 取整容差 0.1px。视口宽 360、390、768、1440、1920px。\n\n修复：λ=0 软阈值必须使用恒等斜率；广义链式法则的集合等式改成直接的 Newton 余项验证；导航测试改为等待目标 DOM 完整更新。修复前记录另附。\n\n资料来源：文再文老师最优化教材与课程网站。教材作者刘浩洋、户将、李勇锋、文再文。原始 65 文件保持字节不变；40 组证明不等于原始 1,990 页全部定理与习题的重写。\n\n浏览器管理策略阻止 file: 导航；用真实 Chromium 加载同一份 HTML，并单独验证源码入口。未测试原生 PDF 查看器、Firefox、Safari、实时网站下载。\n\nHTML SHA-256：{sha}\n'''
(O/'test-report.md').write_text(md)
summary={'generated':stamp,'tests':total,'passed':passed,'failed':failed,'assertions':assertions,'typography_checks':len(font_checks),'text_elements_audited':audited,'min_display_font_px':minimum,'html_sha256':sha,'content':counts};(O/'release-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));print(json.dumps(summary,ensure_ascii=False))
